"""Build a static UI motion storyboard, not a video or animated product demo."""
from pathlib import Path
import json,html,shutil

root=Path(__file__).resolve().parents[1]
dest=root/'design/phase19';dest.mkdir(parents=True,exist_ok=True)
case=json.loads((root/'design/phase16/case-data.json').read_text())
transitions=[]
def motion(id,name,start,end,trigger,meaning,pacing,focus,risk,source):
    transitions.append(dict(id=id,name=name,start=start,end=end,trigger=trigger,meaning=meaning,pacing=pacing,interaction=focus,mobile='Same state order in one column. Preserve current reading position; no camera moves or automatic scroll.',reduced_motion='Instant state replacement; no translation, opacity tween, pulse, smooth scroll or rotating indicator. Keep all status text and announcements.',performance='Only opacity/transform if a transition is used; never animate height, width, blur or layout. No new animation library, decorative request or timer governing state.',risk=risk,implementation_source=source))
motion('M01','Enter the workspace','landing','empty','User activates the workspace link; destination route renders.','The engineer is moving into a task, not watching a launch sequence.','0ms bespoke transition. Use ordinary navigation; landing content is visible at first paint.','Normal route focus/heading behavior; no scroll interception or entrance stagger.','An entrance animation can delay the primary task or hide content when JavaScript fails.','web/src/app/page.tsx; web/src/app/workspace/page.tsx')
motion('M02','Inspect a new digest','empty / result / lookup-error','reading','Validated nonempty digest starts the transaction request.','The old result no longer applies to the new query.','Clear prior query result immediately before request. Status appears at once; optional opacity 120ms on status only. No minimum spinner time.','Retain focus on invoked control. Mark result region busy and announce Reading transaction once. Keep any completed receipt separate and stable.','Fading old evidence out over the new request could misattribute a reviewed result.','inspect(): reset tx/candidates/recallNote; setPhase(reading)')
motion('M03','Reveal chain evidence','reading','recalling','The transaction response establishes failed outcome and memory is configured.','Chain evidence is known; reviewed memory is still being sought.','Show chain evidence immediately. Optional status opacity 120ms; no staging of digest or error lines.','Keep focus. Announce Reading complete. Checking reviewed memory once; busy applies to recall region only.','A single combined success reveal could imply that a failed transaction was repaired.','inspect(): setTx(observed); failed + walrusConfigured; setPhase(recalling); loadRecall()')
motion('M04','Reveal the reviewed precedent','recalling','eligible','Recall response contains a candidate accepted by the existing compatibility checks.','A prior reviewed procedure is now available for human assessment.','One result-region opacity/translateY(4px→0) reveal, 180ms cubic-bezier(.2,.8,.2,1). No stagger, glow, confetti or numeric counter. Entire text/proof enters together; no delayed blob.','Announce Reviewed resolution available once. Keep focus on the initiating control; no autofocus or automatic scroll. All essential information stays outside disclosure.','Animating a link between cases may assert a stronger causal relation than compatibility supports.','loadRecall(): candidates/observedPrecedents/simulationRunbooks/recallUnavailable; existing acceptance guards')
motion('M05','Show honest alternatives','reading / recalling','success / unknown / no-match / unavailable / unconfigured / lookup-error','Actual outcome, configuration check or request failure selects its own branch.','No recommendation is sometimes the correct product outcome. Observation-only records and simulation runbooks remain labelled supporting evidence; they never animate into reviewed resolutions.','Status replaces in place at 0ms; optional 120ms opacity for new status text only. No shake or red full-screen flash.','One concise polite result announcement; input validation is separate. Retry only the relevant read. Preserve accessible transaction evidence and any completed receipt.','No-match must not be substituted for an outage; unknown is not a failed transaction.','inspect() outcome/config branches and catch; loadRecall() recallDegraded/catch')
motion('M06','Inspect supporting provenance','eligible','eligible with secondary details open / closed','User toggles native details summary.','The engineer chooses deeper evidence; the essential decision remains available.','Native open/close, 0ms height animation. No animated accordion.','Keep focus on summary and native expanded semantics. Never hide procedure/reasons/reviewer/full blob.','Animating height shifts the decision out of the reading position and can clip identifiers.','Phase17 native-details contract; existing provenance text')
motion('M07','Open and correct human review','failed evidence / no-match / eligible','review / review with validation errors','User opens editor; invalid submit or proof-method change produces applicable form fields.','The human supplies and approves a specific evidenced resolution.','Editor appears at 0ms, no sliding drawer. Proof-method fields switch instantly. No animation between evidence methods.','User-opened editor focuses heading. Invalid submit focuses correction summary linked to fields; wording matches inline errors. Preserve entered values and require explicit approvals.','Motion must not precheck approval, hide fields, expose private keys or turn an API outage into a field error.','showEditor/proofMethod/verified/confirmedCausalLink state; remember() preconditions')
motion('M08','Submit one reviewed case','review','writing','Valid protected submit starts exactly one remember attempt.','The approval was submitted; durable completion is not yet known.','Show Submitting reviewed resolution immediately. Static wording is sufficient; optional CSS indicator opacity cycle 1000ms, never a progress percentage.','Keep focus; mark write status busy. Prevent duplicate submit through existing handler. Do not animate disabled controls or erase the draft until acceptance.','A filling progress bar would invent completion; a repeated click must not write again.','remember(): writeInFlight/requestId; setPhase(writing); postJson(/api/remember)')
motion('M09','Keep the accepted job visible','writing','pending','Remember response returns an accepted pending job ID.','Storage accepted the request; there is no completed blob yet.','Replace submission status at 0ms. Job ID appears in full with no typewriter effect. Static pending indicator; no ambient pulse.','Announce Storage accepted; completion pending once. Check status is a read of this job. Do not move focus on background status updates.','Pending cannot be a short interstitial that advances after a fixed time.','remember(): result.pending; retainStorage(accepted); checkStorage(accepted)')
motion('M10','Acknowledge durable completion','writing / pending','receipt','Confirmed storage result includes the completed job receipt and Mainnet blob.','The reviewed case has a retained record. This says nothing about repairing the original chain transaction.','Receipt border/status may use one 160ms opacity reveal. Source/job/blob and next action are immediately readable. No pop, burst, bouncing check or count roll-up.','Announce Memory stored once. Keep receipt available across lookup/reload; background completion never steals focus.','Any delayed proof line or inferred success before job completion breaks the evidence claim.','remember() completed proof branch; checkStorage() receipt branch; retainStorage()')
motion('M11','Recover without another write','pending / receipt / storage error','pending / receipt / storage error','Reload restores accepted job/receipt; explicit status read returns its actual state or fails.','An accepted operation can be recovered independently of a new incident lookup.','Restored information renders instantly. No replay of completion animation on hydration. Status-read failure leaves the accepted job and any prior receipt visible.','Keep focus on Check storage status; announce changed state once. No repeated assertive announcements on each poll.','Recovery must never silently call remember again or discard a durable receipt.','session storage initialization; checkStorage(); retainStorage(); failedStorageJob')
motion('M12','Reuse on a distinct failure','receipt / eligible','reading → recalling → eligible / no-match / unavailable / error','User inspects a distinct recurrence, or protected exact-blob verification returns a result.','Retained engineering knowledge becomes useful for a compatible new failure.','Use M02–M05. Compare stable full blob text; no flying token, connector draw or automatic switch to a sample digest.','Receipt stays separate from query result. User chooses the next digest. Exact-recall success wording requires actual equality, never a visual resemblance.','Self-recall, incompatible case or service failure cannot earn the same success state. Failed recall does not invalidate completed storage.','verifySavedRecall(): distinct digest + expectedBlobId; inspect()/loadRecall()')
motion('M13','Copy provenance','eligible / receipt','same state with local copy feedback','Clipboard promise resolves successfully following a user click.','The identifier was copied, not newly verified or saved.','Text feedback immediately; optional 100ms opacity. May clear feedback after 2 seconds, but must not change evidence or focus.','Keep button focus. Polite Copied announcement; failure shows selectable full identifier.','A check icon could be misread as verification; avoid whole-panel animation.','Design Engineering enhancement only: clipboard handler not assumed present')
motion('M14','Recover an unconfirmed submission','writing','response-unconfirmed / rejected review / failed job','Transport failure loses the write response, explicit rejection returns, or status read reports terminal failure.','Unknown acceptance is different from accepted pending, known rejection and known failure.','Replace status immediately, 0ms. No countdown, automatic retry, progress bar or optimistic blob.','Unconfirmed response keeps the original attempt identity and permits existing-job recovery. Known rejection returns the editable review with visible reason; do not precheck approvals. Terminal failed job offers explicit dismissal; read failures preserve accepted job identity. Never infer acceptance without a job ID.','Retrying an ambiguous write could duplicate storage; calling a rejected or failed job pending would mislead the reviewer.','remember() catch RequestError status branch; storageAttempt without jobId; checkStorage() failedStorageJob; pending recovery panel')
manifest=dict(phase=19,date='2026-11-08',type='Static UI motion storyboard; not a rendered animation or production acceptance',direction='Working Precedent',purpose='Help Sui engineers assess and retain reviewed resolutions, then reuse them for compatible failures.',case=case,transitions=transitions,budgets=dict(result_reveal_ms=180,status_feedback_ms=120,receipt_ms=160,maximum_translation_px=4,minimum_wait_ms=0,animation_library_bytes=0),rules=['Business state is driven only by real handler responses, never animation completion or elapsed time.','No scroll-driven evidence reveal or landing parallax.','All content remains accessible without animation; reduced motion is an immediate substitution.','No new writes or live services are used by this storyboard.','Repeated requests must retain existing race/duplicate protection; no new side effects belong in animation callbacks.'],production_qa=['Slow and instant transaction/recall responses do not show stale candidate evidence.','Failed/success/unknown/unconfigured/no-match/unavailable remain distinct.','Protected review keeps both proof methods, all fields and explicit approval controls.','Pending job never displays a blob until actual completion.','Reload/status read recovers the same job and receipt without a new write.','Distinct matching recurrence preserves exact blob; self/mismatch/outage do not show verified reuse.','Keyboard focus and announcements are stable; provenance stays copyable.','Reduced motion removes all tween/loop/smooth-scroll including pseudo-elements.','1440×900,768px and390×844 retain reading order and no clipping.','Record actual product state sequences at Phase22; static storyboard QA cannot accept runtime motion.'])
(dest/'motion.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
text='''# Rouse Phase 19 motion storyboard — 2026-11-08

## Product purpose and motion decision

The engineer needs to inspect a failure, assess prior reviewed judgment and retain an evidenced resolution for later reuse. Motion makes changes in evidence understandable. It must never imply that Rouse executed a repair. Working Precedent remains the selected composition; no new visual territory is needed.

**Direction: evidence changes in place.** The page stays still while its actual state becomes clearer. Landing content and primary action appear at first paint. No scroll reveals, camera moves, parallax, typewriter proof, progress percentages, flying blobs or sequential card entrances. The magic moment is a distinct failure retrieving an inspectable prior resolution; the full procedure, reasons, reviewer and exact blob arrive together.

This deliverable is a static UI storyboard and implementation contract. It is not an animated app, recorded live sequence, launch film or final motion QA. Existing Phase 16 captures are labelled composition references; they cannot prove backend state transitions. Demo production remains a later phase.

## Grammar and time

One optional result reveal: opacity 0→1 and translateY 4px→0 over 180ms, cubic-bezier(.2,.8,.2,1). Local status feedback ≤120ms; receipt acknowledgment ≤160ms. Text/proof updates immediately in the DOM; animation never delays announcement, interaction or a response. There is no minimum loading duration. Do not animate a result that arrives before a loading paint just to demonstrate a spinner. Clear obsolete query results synchronously, without exit animation; keep durable receipts in their separate region.

Only opacity and transform may tween. No animation library is required. No animated layout, height, width, blur, background filter, infinite success effect or data request for ornament. Loading uses explicit text; one optional 1000ms opacity indicator is allowed only while an actual foreground request is running. Accepted storage pending is a durable status, not a spinner that promises imminent completion. No automatic write/retry or business transition may run from an animation callback. Durations and byte budgets here are targets, not measured implementation performance.

## Transition contract

'''
for m in transitions:
    text+=f"### {m['id']} — {m['name']}\n\n**{m['start']} → {m['end']}**\n\nTrigger: {m['trigger']}\n\nMeaning: {m['meaning']}\n\nPacing: {m['pacing']}\n\nInteraction and focus: {m['interaction']}\n\nMobile: {m['mobile']}\n\nReduced motion: {m['reduced_motion']}\n\nPerformance: {m['performance']}\n\nRisk: {m['risk']}\n\nHandler binding: `{m['implementation_source']}`. These are semantic bindings in current source; the final DOM/announcement hooks remain implementation work.\n\n"
text+='''## Responsive, focus and announcements

Desktop keeps current evidence and prior judgment paired. Mobile stacks them in decision order; status updates never scroll the document to a newly loaded result. The user can navigate by headings or activate a result link. Native details opens secondary information with no animated height. Essential proof is never in collapsed content. Keep the active control mounted when possible. If replacing a user-opened editor would remove the focused control, restore focus to its opener; background completion should update a persistent status region instead of unmounting the focused form. Invalid submission moves focus deliberately to an accessible correction summary; operational failures use their own status region.

Use one persistent polite live region with concise state messages, not the entire digest/procedure/receipt as a live region. Announce changes, not polling ticks. Clear busy independently for transaction, recall and storage operations. Error wording remains visible; never rely on a toast, color, sound or movement alone. No aria-live field contains secrets or the private reviewer key.

`prefers-reduced-motion: reduce` removes every transform/opacity animation, spinner/pseudo-element loop and smooth scroll. It does not hide information, remove status wording or substitute a timer. Motion disabled in the browser and a slow-device path must give the same decisions and exact identifiers.

## Storyboard frames and capture boundary

The HTML sheet pairs six existing static targets with captions about the real event between them. Separate intermediate events are named explicitly; a pair of frames is not a demonstration that the intermediate request completed. The reviewed-case data is bound to the original source, distinct recurrence and exact blob in motion.json. Original operator deployment remains unknown; the correction is an independently tested integration procedure. Preserve immutable Casewake proof URLs.

The review→pending→receipt frames are targets, not a new human approval or storage request. For final demo footage, use the existing approved receipt and read-only recurrence. A future new case needs its own evidence and approval. Phase 27 must rewrite the historical demo script; do not reuse its obsolete simulation/inventory narrative.

## Acceptance and handoff

Pass this phase only when each meaningful transition has trigger, start/end, meaning, pacing, interaction/scroll relation, mobile/reduced-motion fallback, performance constraint, risk and source binding. The manifest and responsive sheet are checked independently. Phase 20 must freeze the composition/state contract before broad implementation. Design Engineering may plan from this storyboard; full implementation remains gated by design lock.

Phase 22 must record the real application at desktop/tablet/mobile with normal and reduced motion, slow/instant responses, keyboard focus, errors, recovery and exact-blob reuse. Confirm that no animation event can trigger a write or alter compatibility, and no stale evidence survives a new query. Static board QA cannot close production motion QA. Final application motion is NOT VERIFIED.
'''
(dest/'STORYBOARD.md').write_text(text,encoding='utf-8')
(root/'MOTION_STORYBOARD_ROUSE_2026-11-08.md').write_text(text,encoding='utf-8')
pairs=[('01 / READ, THEN RECALL','M02–M04','workspace-loading-desktop.png','workspace-eligible-desktop.png','Reading transaction','Reviewed candidate available','A failed chain response first starts recall. Only an accepted recall response reveals the candidate. No timed success.'),('02 / HUMAN APPROVAL','M07–M09','workspace-review-desktop.png','workspace-pending-desktop.png','Explicit human review','Accepted storage job','Only a protected valid submission can produce an accepted job. The study submits nothing; pending has no completed blob.'),('03 / DURABLE RECEIPT','M09–M11','workspace-pending-desktop.png','workspace-receipt-desktop.png','Completion pending','Completed receipt','The completed job response, not elapsed time, permits the receipt. Reload recovers it without replaying a write or celebration.'),('04 / USE IT AGAIN','M12','workspace-receipt-desktop.png','workspace-eligible-desktop.png','Original receipt retained','Distinct recurrence inspected','The user selects a new failure. Compatibility and exact-blob equality require real responses; the receipt stays independently valid.'),('05 / SERVICE FAILURE','M05','workspace-eligible-desktop.png','workspace-unavailable-desktop.png','Earlier query result','Memory unavailable for new query','Clear the earlier candidate immediately when a new query begins. An outage is not no-match; no fading stale procedure behind it.'),('06 / INVESTIGATE AND REVIEW','M05–M07','workspace-no-match-desktop.png','workspace-review-desktop.png','No eligible precedent','Human chooses review','No-match offers investigation and review. It never auto-opens the editor or supplies invented cause/fix text.')]
media=dest/'frames';media.mkdir(exist_ok=True)
cards=[]
for title,ids,start,end,a,b,note in pairs:
    for n in [start,end]:shutil.copyfile(root/'evidence/phase16'/n,media/n)
    frames=''.join(f'<figure><a href="frames/{n}"><img src="frames/{n}" alt="Recorded design target: {html.escape(label)}"></a><figcaption>{html.escape(label)}</figcaption></figure>' for n,label in [(start,a),(end,b)])
    cards.append(f'<article><div class="eyebrow">{title} / {ids}</div><div class="pair">{frames}</div><p>{html.escape(note)}</p></article>')
rows=''.join(f'<tr><th scope="row">{m["id"]}<br>{html.escape(m["name"])}</th><td>{html.escape(m["trigger"])}</td><td>{html.escape(m["pacing"])}</td></tr>' for m in transitions)
css='''*{box-sizing:border-box}body{margin:0;background:#f5f5ef;color:#0e1212;font-family:system-ui,sans-serif}main{max-width:1260px;margin:auto;padding:48px 28px}header{max-width:940px}h1{font-size:clamp(34px,5vw,64px);line-height:1.05;margin:20px 0}p{font-size:17px;line-height:1.6}.eyebrow{font:12px ui-monospace,monospace;line-height:1.6}aside{background:#dceacb;padding:22px;margin:28px 0;line-height:1.6}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}article{border-top:1px solid #34403d;padding:24px 0}figure{margin:20px 0 0;min-width:0}figure a{display:block;background:#17201c;padding:10px}img{width:100%;height:310px;object-fit:contain}figcaption{font-weight:650;margin-top:10px}a{color:inherit}a:focus-visible{outline:3px solid #34403d;outline-offset:4px}h2{margin-top:40px;font-size:28px}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{vertical-align:top;text-align:left;padding:16px 10px;border-top:1px solid #a1aaa5;line-height:1.6;overflow-wrap:anywhere}th{width:22%}footer{padding:30px 0;font-size:16px;line-height:1.7}@media(max-width:700px){main{padding:28px 20px}.pair{grid-template-columns:1fr;gap:0}img{height:240px}table,tbody,tr,th,td{display:block;width:100%}thead{display:none}tr{padding:18px 0;border-top:1px solid #a1aaa5}th,td{border:0;padding:6px 0}td:before{display:block;font-weight:650}td:nth-child(2):before{content:'Trigger'}td:nth-child(3):before{content:'Pacing'}}'''
(dest/'style.css').write_text(css)
doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>Rouse / motion storyboard</title><link rel="stylesheet" href="style.css"></head><body><main><header><div class="eyebrow">ROUSE / PHASE 19 / WORKING PRECEDENT</div><h1>The page stays still.<br>The evidence becomes clear.</h1><p>Motion follows the engineer’s work: inspect, assess, review, retain and reuse. Every change names the real event that allows it.</p></header><aside><strong>Static storyboard — recorded design targets.</strong><br>These paired frames do not perform lookups, approve a case, store memory or verify a transition. Open a frame at full size to inspect its composition. <a href="STORYBOARD.md">Full motion contract</a> · <a href="motion.json">Transition manifest</a></aside>'+''.join(cards)+'<h2>Fourteen transition contracts</h2><p>Reduced motion substitutes immediate state changes everywhere. No animation callback controls a request or a result.</p><table><thead><tr><th>Transition</th><th>Real trigger</th><th>Pacing</th></tr></thead><tbody>'+rows+'</tbody></table><footer><strong>Next: Phase 20 design lock.</strong><br>Actual application motion, focus and state sequences require implementation and Phase 22 recording. This sheet has no animation runtime, APIs or storage actions.</footer></main></body></html>'
(dest/'index.html').write_text(doc,encoding='utf-8')
print(json.dumps({'transitions':len(transitions),'frame_pairs':len(pairs),'scope':'static UI storyboard'}))
